package com.vandorlabs.neoforge.door;
import com.google.gson.*;
import com.vandorlabs.neoforge.fluid.NativeFluidSlots;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.*;
import net.neoforged.neoforge.fluids.FluidStack;
import java.nio.file.*;
/** Frozen actual Forge transitions replayed against actual native linked hosts. */
final class DoorGushChecks {
 static void run(ServerLevel level,NativeProgrammableDoorEntity owner)throws Exception{
  int cases=0;BlockPos pos=owner.getBlockPos();var upper=(NativeProgrammableDoorEntity)level.getBlockEntity(pos.above());owner.installPlacement(NativeDoorSettings.fresh(false,true),com.vandorlabs.redstone.ChannelList.EMPTY);upper.installPlacement(NativeDoorSettings.fresh(false,true),com.vandorlabs.redstone.ChannelList.EMPTY);var old=owner.getBlockState();var oldUpper=upper.getBlockState();var neighbors=new java.util.HashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();for(int h=0;h<2;h++)for(Direction d:Direction.Plane.HORIZONTAL){BlockPos out=pos.above(h).relative(d);neighbors.put(out,level.getBlockState(out));}
  try(var lines=Files.lines(Path.of(System.getProperty("vandorlabs.doorGushReference")))){for(String line:(Iterable<String>)lines::iterator){var row=JsonParser.parseString(line).getAsJsonObject();Direction face=Direction.from3DDataValue(row.get("face").getAsInt());boolean open=row.get("open").getAsBoolean(),stop=row.get("stop").getAsBoolean();int half=row.get("half").getAsInt(),target=row.get("target").getAsInt();
   level.setBlock(pos,old.setValue(NativeProgrammableDoorBlock.FACING,face).setValue(NativeProgrammableDoorBlock.OPEN,open),Block.UPDATE_CLIENTS);level.setBlock(pos.above(),oldUpper.setValue(NativeProgrammableDoorBlock.FACING,face).setValue(NativeProgrammableDoorBlock.OPEN,!open),Block.UPDATE_CLIENTS);
   for(var host:new NativeProgrammableDoorEntity[]{owner,upper})for(int side=0;side<2;side++)host.containedFluids().set(side,FluidStack.EMPTY,level.registryAccess());var selected=half==0?owner:upper;var raw=selected.saveWithoutMetadata(level.registryAccess());var slots=new net.minecraft.nbt.CompoundTag();for(int side=0;side<2;side++){int kind=row.get(side==0?"first":"second").getAsInt();if(kind!=0){var tag=new net.minecraft.nbt.CompoundTag();tag.putString("FluidName",kind==1?"water":kind==2?"lava":"fixture:unknown");tag.putInt("Amount",1000);slots.put("Side"+side,tag);}}raw.put(NativeFluidSlots.KEY,slots);selected.loadWithComponents(raw,level.registryAccess());owner.setWaterOutlets(row.get("previous").getAsBoolean()?255:0);
   var state=target==0?Blocks.AIR.defaultBlockState():target==1?Blocks.WATER.defaultBlockState():target==2?Blocks.WATER.defaultBlockState().setValue(LiquidBlock.LEVEL,3):target==3?Blocks.LAVA.defaultBlockState():target==4?Blocks.STONE.defaultBlockState():Blocks.SHORT_GRASS.defaultBlockState();for(BlockPos at:neighbors.keySet())level.setBlock(at,state,Block.UPDATE_CLIENTS);
   NativeDoorWaterGush.update(owner,stop);if(owner.waterOutlets()!=row.get("mask").getAsInt())throw new AssertionError("Native gush ownership "+row+" actual="+owner.waterOutlets());var expected=row.getAsJsonArray("states");for(int h=0;h<2;h++)for(int d=0;d<4;d++){var s=level.getBlockState(pos.above(h).relative(Direction.from2DDataValue(d)));int actual=s.getBlock() instanceof LiquidBlock&&s.getFluidState().is(net.minecraft.tags.FluidTags.WATER)?s.getValue(LiquidBlock.LEVEL):target==0?-1:target==3?-3:target==4?-4:-5;if(actual!=expected.get(h*4+d).getAsInt())throw new AssertionError("Native gush outlet "+row+" half="+h+" direction="+d+" actual="+actual);}cases++;
  }}finally{owner.setWaterOutlets(0);for(var host:new NativeProgrammableDoorEntity[]{owner,upper})for(int side=0;side<2;side++)host.containedFluids().set(side,FluidStack.EMPTY,level.registryAccess());level.setBlock(pos,old,Block.UPDATE_CLIENTS);level.setBlock(pos.above(),oldUpper,Block.UPDATE_CLIENTS);neighbors.forEach((at,state)->level.setBlock(at,state,Block.UPDATE_CLIENTS));}
  if(cases!=6144)throw new AssertionError("Native gush coverage "+cases);System.out.println("[vandorlabs][door-gush] PASS cases="+cases+" actual linked hosts/opaque sides/independent upper OPEN/existing source/flowing water/obstructions/removal decisions");
 }
 private static void need(boolean condition,String message){if(!condition)throw new AssertionError("Native gush restart "+message);}
 static void write(ServerLevel level,BlockPos pos,NativeProgrammableDoorBlock block){
  level.getChunkAt(pos);level.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),Block.UPDATE_CLIENTS);var state=block.defaultBlockState().setValue(NativeProgrammableDoorBlock.FACING,Direction.NORTH);level.setBlock(pos,state,Block.UPDATE_CLIENTS);level.setBlock(pos.above(),state.setValue(NativeProgrammableDoorBlock.HALF,net.minecraft.world.level.block.state.properties.DoubleBlockHalf.UPPER),Block.UPDATE_CLIENTS);var owner=(NativeProgrammableDoorEntity)level.getBlockEntity(pos);owner.installPlacement(NativeDoorSettings.fresh(false,true),com.vandorlabs.redstone.ChannelList.EMPTY);owner.containedFluids().set(0,new FluidStack(net.minecraft.world.level.material.Fluids.WATER,777),level.registryAccess());NativeDoorLifecycle.toggle(level,pos);need(owner.waterOutlets()==4&&level.getBlockState(pos.north()).getFluidState().isSource(),"manual open publishes owned source");need(!owner.getUpdateTag(level.registryAccess()).contains("DoorWaterOutlets")&&!owner.itemSettings().contains("DoorWaterOutlets"),"ownership is saved server state only");
  for(int distance=1;distance<=9;distance++){BlockPos channel=pos.north(distance);level.setBlock(channel.below(),Blocks.STONE.defaultBlockState(),Block.UPDATE_CLIENTS);level.setBlock(channel.east(),Blocks.STONE.defaultBlockState(),Block.UPDATE_CLIENTS);level.setBlock(channel.west(),Blocks.STONE.defaultBlockState(),Block.UPDATE_CLIENTS);}for(int tick=0;tick<40;tick++){flow(level,pos);NativeDoorWaterGush.update(owner,false);}need(level.getFluidState(pos.north(6)).is(net.minecraft.tags.FluidTags.WATER),"vanilla fluid ticks reach channel end");
  System.out.println("[vandorlabs][door-gush-restart] write PASS owned source saved/sustained native vanilla channel flow");
 }
 static void read(ServerLevel level,BlockPos pos){
  level.getChunkAt(pos);var owner=(NativeProgrammableDoorEntity)level.getBlockEntity(pos);need(owner!=null&&owner.waterOutlets()==4&&owner.containedFluids().get(0).getAmount()==777,"source ownership and independent stored amount survive process restart");NativeDoorLifecycle.toggle(level,pos);need(owner.waterOutlets()==0&&level.getBlockState(pos.north()).getValue(LiquidBlock.LEVEL)==1,"closing releases owned source");for(int tick=0;tick<80;tick++)flow(level,pos);need(level.getFluidState(pos.north(6)).isEmpty(),"closed vanilla channel drains");NativeDoorLifecycle.toggle(level,pos);need(owner.waterOutlets()==4,"reopening feeds draining water again");level.removeBlock(pos,false);need(level.getBlockState(pos.north()).getValue(LiquidBlock.LEVEL)==1,"real owner removal releases source before tile removal");
  System.out.println("[vandorlabs][door-gush-restart] read PASS close/reopen/actual removal source release");
 }

 private static void flow(ServerLevel level,BlockPos root){for(int i=1;i<=9;i++){BlockPos at=root.north(i);var state=level.getFluidState(at);if(state.is(net.minecraft.tags.FluidTags.WATER))state.tick(level,at);}}

}
